// Selected variant A, generated during the character-style exploration.
// Embedded once so Node and Worker hosts use the exact same reference without external fetches.
const pngBase64='';
let reference;
export function characterStyleReference(){
  if(!reference){const binary=atob(pngBase64),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);reference=new Blob([bytes],{type:'image/png'});}
  return reference;
}